import re
from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class RmodParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        radio_ent = self.enb_ent_config['radios'][self.radio_num]
        self.set_parameter('prodCodePlanned', radio_ent['prod_code_planned'])
        self.set_parameter('protocol', 'NOKIA')
        self.set_parameter('ptpSyncRepPrd', 10)
        self.set_parameter('internetProtocolVersion', 'IPV4')

        linkSpeed = radio_ent.get('link_speed')
        if linkSpeed and not re.match(r'ecpri', radio_ent['link_speed'], re.IGNORECASE):
            self.set_parameter('linkSpeed', linkSpeed)
        if re.match(r'ORAN', radio_ent['type']):
            self.set_parameter('protocol', 'O-RAN')
            self.set_parameter('syncERepPrd', 10)
